layout_css:
.poster-canvas {
  max-width: 680px;
  aspect-ratio: 1 / 1.414;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
}
.poster-badge {
  display: inline-block;
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border: 1px solid currentColor;
  border-radius: 999px;
  margin-bottom: 12px;
}
.poster-hero-title {
  font-size: clamp(28px, 5vw, 44px);
  font-weight: 900;
  line-height: 1.15;
  margin: 8px 0 16px;
}
.poster-visual-box {
  flex: 1;
  min-height: 200px;
  margin: 16px 0;
  border-radius: 12px;
  border: 2px dashed rgba(148, 163, 184, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 20px;
}
.poster-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 12px;
  padding-top: 16px;
  border-top: 2px solid rgba(148, 163, 184, 0.3);
}
.poster-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid rgba(148, 163, 184, 0.25);
}
.poster-qr-placeholder {
  width: 64px;
  height: 64px;
  border: 2px solid currentColor;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: bold;
}
